// Package popcount is the reference kernel for popcount(xs []uint64) int: the
// total number of set bits in xs.
//
// The native stage (pkg/native) copies this directory and replaces this file
// with a genome printed as Popcount, so the tests and benchmarks in
// popcount_test.go run against the genome unchanged.
package popcount

import "math/bits"

// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	l := len(xs)
	if l >= 16 {
		// Peel 16 words; exactly 16 returns without a recursive call.
		n := bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3]) +
			bits.OnesCount64(xs[4]) + bits.OnesCount64(xs[5]) +
			bits.OnesCount64(xs[6]) + bits.OnesCount64(xs[7]) +
			bits.OnesCount64(xs[8]) + bits.OnesCount64(xs[9]) +
			bits.OnesCount64(xs[10]) + bits.OnesCount64(xs[11]) +
			bits.OnesCount64(xs[12]) + bits.OnesCount64(xs[13]) +
			bits.OnesCount64(xs[14]) + bits.OnesCount64(xs[15])
		if l == 16 {
			return n
		}
		return n + Popcount(xs[16:])
	}
	if l >= 8 {
		n := bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3]) +
			bits.OnesCount64(xs[4]) + bits.OnesCount64(xs[5]) +
			bits.OnesCount64(xs[6]) + bits.OnesCount64(xs[7])
		if l >= 12 {
			n += bits.OnesCount64(xs[8]) + bits.OnesCount64(xs[9]) +
				bits.OnesCount64(xs[10]) + bits.OnesCount64(xs[11])
			if l == 12 {
				return n
			}
			if l == 13 {
				return n + bits.OnesCount64(xs[12])
			}
			n += bits.OnesCount64(xs[12]) + bits.OnesCount64(xs[13])
			if l == 14 {
				return n
			}
			return n + bits.OnesCount64(xs[14])
		}
		if l >= 10 {
			n += bits.OnesCount64(xs[8]) + bits.OnesCount64(xs[9])
			if l == 11 {
				return n + bits.OnesCount64(xs[10])
			}
			return n
		}
		if l == 9 {
			return n + bits.OnesCount64(xs[8])
		}
		return n
	}
	if l >= 4 {
		n := bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3])
		if l >= 6 {
			n += bits.OnesCount64(xs[4]) + bits.OnesCount64(xs[5])
			if l == 7 {
				return n + bits.OnesCount64(xs[6])
			}
			return n
		}
		if l == 5 {
			return n + bits.OnesCount64(xs[4])
		}
		return n
	}
	if l >= 2 {
		if l == 3 {
			return bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
				bits.OnesCount64(xs[2])
		}
		return bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1])
	}
	if l == 1 {
		return bits.OnesCount64(xs[0])
	}
	return 0
}

// popcountSWAR is the old software-popcount variant (unused, kept for reference).
func popcountSWAR(xs []uint64) int {
	const (
		m1 = 0x5555555555555555
		m2 = 0x3333333333333333
		m4 = 0x0f0f0f0f0f0f0f0f
		m8 = 0x00ff00ff00ff00ff
		h  = 0x0001000100010001
	)
	n := 0
	for len(xs) >= 12 {
		a, b, c := xs[0], xs[1], xs[2]
		a -= a >> 1 & m1
		b -= b >> 1 & m1
		c -= c >> 1 & m1
		a = a&m2 + a>>2&m2
		b = b&m2 + b>>2&m2
		c = c&m2 + c>>2&m2
		a += b + c
		s := a&m4 + a>>4&m4

		a, b, c = xs[3], xs[4], xs[5]
		a -= a >> 1 & m1
		b -= b >> 1 & m1
		c -= c >> 1 & m1
		a = a&m2 + a>>2&m2
		b = b&m2 + b>>2&m2
		c = c&m2 + c>>2&m2
		a += b + c
		s += a&m4 + a>>4&m4

		a, b, c = xs[6], xs[7], xs[8]
		a -= a >> 1 & m1
		b -= b >> 1 & m1
		c -= c >> 1 & m1
		a = a&m2 + a>>2&m2
		b = b&m2 + b>>2&m2
		c = c&m2 + c>>2&m2
		a += b + c
		s += a&m4 + a>>4&m4

		a, b, c = xs[9], xs[10], xs[11]
		a -= a >> 1 & m1
		b -= b >> 1 & m1
		c -= c >> 1 & m1
		a = a&m2 + a>>2&m2
		b = b&m2 + b>>2&m2
		c = c&m2 + c>>2&m2
		a += b + c
		s += a&m4 + a>>4&m4

		s = s&m8 + s>>8&m8
		n += int(s * h >> 48)
		xs = xs[12:]
	}
	if len(xs) >= 3 {
		var s uint64
		for len(xs) >= 3 {
			a, b, c := xs[0], xs[1], xs[2]
			a -= a >> 1 & m1
			b -= b >> 1 & m1
			c -= c >> 1 & m1
			a = a&m2 + a>>2&m2
			b = b&m2 + b>>2&m2
			c = c&m2 + c>>2&m2
			a += b + c
			s += a&m4 + a>>4&m4
			xs = xs[3:]
		}
		s = s&m8 + s>>8&m8
		n += int(s * h >> 48)
	}
	switch len(xs) {
	case 2:
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1])
	case 1:
		n += bits.OnesCount64(xs[0])
	}
	return n
}

